def f(gi, overlap=True):
    H=len(gi);W=len(gi[0])
    g=[row[:] for row in gi]
    allS={(y,x) for y in range(H) for x in range(W) if gi[y][x]==8}
    cs=comps_of(allS)
    for Cset in cs:
        C=frozenset(Cset)
        sols=[]
        def dfs(cov,stack):
            if cov==C: sols.append(list(stack)); return
            if len(stack)>len(C)+1: return
            rem=C-cov
            c=min(rem)
            for name,(r0,c0),occ in allpl:
                inter=len(occ & cov)
                if not (inter>0 and not overlap) and occ<=C:
                    dfs(cov|occ, stack+[(name,r0,c0)])
        dfs(frozenset(),[])
        g0=[row[:] for row in gi]
        best=None
        for s in sols:
            # compute mismatched count
            mis=0
            for n,r0,c0 in s:
                for a,b in pieces[n]:
                    rr,cc=r0+a,c0+b
                    if g0[rr][cc]==8:
                        if overlap: mis+=1  # overlaps allowed/prioritize fewest overlaps? 
            if best is None or mis<best[0]: best=(mis,s)
        for n,r0,c0 in best[1]:
            for a,b in pieces[n]:
                rr,cc=r0+a,c0+b
                if g0[rr][cc]==8: g[rr][cc]=colmap.get(n,-1)
    return g
