def comps(g):
    R=len(g); C=len(g[0]); seen=set(); out=[]
    for i in range(R):
        for j in range(C):
            if g[i][j] and (i,j) not in seen:
                stack=[(i,j)]; cells=[]
                while stack:
                    y,x=stack.pop()
                    if (y,x) in seen: continue
                    seen.add((y,x)); cells.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<R and 0<=nx<C and g[ny][nx] and (ny,nx) not in seen: stack.append((ny,nx))
                out.append(cells)
    return out
